#include <game/pxdvs/app/effects/filterPrivate.hpp>
void operator delete(void*);
struct FloorData;
extern "C" {void*GSfilterCreate(FilterColor*);void GSfilterFree(void*);void GSfilterSetColor(void*,FilterColor*);void GSlogWrite(const char*,...);void GSmodelDisableModulation(void*);void GSmodelEnableModulation(void*,FilterColor*);void GSmodelGetModulationColor(void*,FilterColor*);u8 GSmodelIsModulationEnabled(void*);void GSmodelResetPEdescr(void*);void GSmodelSetModulationColor(void*,FilterColor*);void GSmodelSetPEdescr(void*,void*);void*GSresGetResource(u32,u32);void**HSD_ArchiveGetPublicAddress(void*,const char*);FloorData*floorDataBiosGetCurrentPtr();u32 floorDataBiosGetMapResID(FloorData*);u32 floorGetCurrentGroupID();u32 floorReadMakeModelResID(u32);}
filterEffect::~filterEffect(){Stop();}
bool filterEffect::_update(f32){if(modulation){UpdateModulation();}else if(target){GSfilterSetColor(target,&color);}else return false;return true;}
void filterEffect::_stop(){if(modulation){if(target){if(saved)GSmodelSetModulationColor(target,&original);else GSmodelDisableModulation(target);if(pe)GSmodelResetPEdescr(target);}else{u32 modelResource;void**scene;u32 resource;u32 group;u32 index;u32 offset;void*model;group=floorGetCurrentGroupID();resource=floorDataBiosGetMapResID(floorDataBiosGetCurrentPtr());index=0;void*archive=GSresGetResource(group,resource);if(archive){scene=HSD_ArchiveGetPublicAddress(archive,"scene_data");if(scene&&*scene){modelResource=floorReadMakeModelResID(resource);for(;((void**)*scene)[index];index++){model=GSresGetResource(group,modelResource|index);if(model){GSmodelDisableModulation(model);if(pe)GSmodelResetPEdescr(model);}}}}}}else if(target)GSfilterFree(target);}
bool filterEffect::_start(){if(modulation){InitModulation();}else{target=GSfilterCreate(&color);if(!target){GSlogWrite("filterStart: Could not start filter effect - invalid filter!\n");return false;}}return true;}
void filterEffect::UpdateModulation(){FilterColor result;if(saved){f32 value=((f32)original.r+(f32)color.r)-128.0f;if(value<0)value=0;else if(value>255)value=255;result.r=value;value=((f32)original.g+(f32)color.g)-128.0f;if(value<0)value=0;else if(value>255)value=255;result.g=value;value=((f32)original.b+(f32)color.b)-128.0f;if(value<0)value=0;else if(value>255)value=255;result.b=value;result.a=((f32)original.a*(f32)color.a)/255.0f;}else{result.r=color.r;result.g=color.g;result.b=color.b;result.a=color.a;}if(target){GSmodelSetModulationColor(target,&result);return;}u32 modelResource;void**scene;u32 resource;u32 group;u32 index;u32 offset;void*model;group=floorGetCurrentGroupID();resource=floorDataBiosGetMapResID(floorDataBiosGetCurrentPtr());index=0;void*archive=GSresGetResource(group,resource);if(archive){scene=HSD_ArchiveGetPublicAddress(archive,"scene_data");if(scene&&*scene){modelResource=floorReadMakeModelResID(resource);for(;((void**)*scene)[index];index++){model=GSresGetResource(group,modelResource|index);if(model)GSmodelSetModulationColor(model,&result);}}}}
void filterEffect::InitModulation(){static u8 pedesc[]={0x33,0,0,0xFF,1,4,5,15,1,4,1,0};saved=0;if(target){if(pe)GSmodelSetPEdescr(target,pedesc);if(!GSmodelIsModulationEnabled(target)){GSmodelEnableModulation(target,&color);return;}if(combine){saved=1;GSmodelGetModulationColor(target,&original);return;}GSmodelSetModulationColor(target,&color);return;}u32 modelResource;void**scene;u32 resource;u32 group;u32 index;u32 offset;void*model;group=floorGetCurrentGroupID();resource=floorDataBiosGetMapResID(floorDataBiosGetCurrentPtr());index=0;void*archive=GSresGetResource(group,resource);if(archive){scene=HSD_ArchiveGetPublicAddress(archive,"scene_data");if(scene&&*scene){modelResource=floorReadMakeModelResID(resource);for(;((void**)*scene)[index];index++){model=GSresGetResource(group,modelResource|index);if(model){if(pe)GSmodelSetPEdescr(model,pedesc);GSmodelEnableModulation(model,&color);}}}}}
